function CountLowercaseOdd(txt: string): int
    reads txt
    ensures 0 <= CountLowercaseOdd(txt) <= |txt|
    decreases |txt|
{
    if |txt| == 0 then
        return 0;
    else
        var first := txt[0];
        var rest := txt[1..];
        if first >= 'a' && first <= 'z' && (ord(first) % 2 == 1) then
            return 1 + CountLowercaseOdd(rest);
        else
            return CountLowercaseOdd(rest);
}

